/*
 * Pro tips
 * - Swap BOTH next and prev for every node, not just the values.
 * - After swapping, current.prev points to the ORIGINAL next node: follow it to continue.
 * - Keep the last processed node as the new head. Its prev must be null.
 * - Check empty, singleton, and two-node lists; verify backward links as well as printed order.
 * - Reversal uses O(n) time and O(1) extra space; the supplied list-building helper separately allocates O(n) space.
 */

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Scanner;
import java.util.function.Function;

class Solution {
    static class DoublyNode<T> {
        T val;
        DoublyNode<T> next;
        DoublyNode<T> prev;

        DoublyNode(T val) {
            this.val = val;
            this.next = null;
            this.prev = null;
        }

        DoublyNode(T val, DoublyNode<T> next, DoublyNode<T> prev) {
            this.val = val;
            this.next = next;
            this.prev = prev;
        }
    }

    public static DoublyNode<Integer> reverseDoublyLinkedList(DoublyNode<Integer> head) {
        if (head == null) {
            return null;
        }

        DoublyNode<Integer> current = head;
        DoublyNode<Integer> newHead = null;

        while (current != null) {
            newHead = current;
            DoublyNode<Integer> temp = current.prev;
            current.prev = current.next;
            current.next = temp;
            current = current.prev; // the original next node
        }

        return newHead;
    }

    public static <T> DoublyNode<T> buildDoublyList(Iterator<String> it, Function<String, T> f) {
        List<T> vals = new ArrayList<>();
        while (it.hasNext()) {
            String s = it.next();
            if (!s.isEmpty()) vals.add(f.apply(s));
        }
        if (vals.isEmpty()) return null;

        DoublyNode<T> head = new DoublyNode<>(vals.get(0));
        DoublyNode<T> current = head;
        for (int i = 1; i < vals.size(); i++) {
            DoublyNode<T> node = new DoublyNode<>(vals.get(i), null, current);
            current.next = node;
            current = node;
        }
        return head;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static <T> void formatDoublyList(DoublyNode<T> node, List<String> result) {
        while (node != null) {
            result.add(String.valueOf(node.val));
            node = node.next;
        }
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        DoublyNode<Integer> head = buildDoublyList(splitWords(scanner.nextLine()).iterator(), Integer::parseInt);
        scanner.close();
        DoublyNode<Integer> res = reverseDoublyLinkedList(head);
        ArrayList<String> resArr = new ArrayList<>();
        formatDoublyList(res, resArr);
        System.out.println(String.join(" ", resArr));
    }
}
